const wh = $input.first().json;
const body = (wh.application_id !== undefined) ? wh : (wh.body || wh);

const appId = body.application_id;
const callbackUrl = body.callback_url;

if (!appId || !callbackUrl) {
  throw new Error('Dados em falta: application_id=' + appId + ' callback_url=' + callbackUrl);
}

const skills = String(body.candidate_skills || '').slice(0, 2000);
const summary = String(body.candidate_summary || '').slice(0, 1000);
const experience = String(body.candidate_experience || '').slice(0, 2000);
const jobTitle = String(body.job_title || '');
const requirements = String(body.job_requirements || '').slice(0, 3000);

const prompt = 'Compara o candidato com a vaga. Responde APENAS com JSON valido com: similarity_score (0-100) e match_feedback.\n\nCandidato - Skills: ' + skills + ' | Resumo: ' + summary + ' | Experiencia: ' + experience + '\nVaga: ' + jobTitle + ' | Requisitos: ' + requirements;

// Construir o body do pedido Ollama aqui garante que stream é boolean false (não string)
const ollamaBody = JSON.stringify({
  model: 'llama3.2:1b',
  stream: false,
  format: 'json',
  prompt: prompt
});

return [{ json: { application_id: appId, callback_url: callbackUrl, prompt: prompt, ollama_body: ollamaBody } }];

const ollamaResp = $input.first().json;
const metadata = $('Construir Prompt Score').first().json;

let result = {};
try {
  const raw = String(ollamaResp.response || ollamaResp.text || '{}');
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  result = JSON.parse(cleaned);
} catch(e) {
  result = {};
}

const similarityScore = Math.min(100, Math.max(0, parseFloat(result.similarity_score) || 0));
const matchFeedback = String(result.match_feedback || 'Analise nao disponivel.').trim();

return [{
  json: {
    application_id: metadata.application_id,
    callback_url: metadata.callback_url,
    payload: JSON.stringify({ similarity_score: similarityScore, match_feedback: matchFeedback })
  }
}];
